 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    patterns = []
    for r in (0, h - 1):
        vals = grid[r]
        nz = [i for i, v in enumerate(vals) if v]
        if nz:
            # Treat each contiguous nonzero run as an ordered cyclic template.
            runs = []
            run = [nz[0]]
            for i in nz[1:]:
                if i == run[-1] + 1:
                    run.append(i)
                else:
                    runs.append(run); run = [i]
            runs.append(run)
            for rr in runs:
                patterns.append((rr[0], [vals[i] for i in rr], r))
    seed_cells = {(r,c) for r in (0,h-1) for c,v in enumerate(grid[r]) if v}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if not v or (r,c) in seed_cells:
                continue
            candidates = [p for p in patterns if v in p[1]]
            if not candidates:
                continue
            _, seq, _ = candidates[0]
            k = seq.index(v)
            start = c-k
            for j in range(len(seq)):
                x = start+j
                if 0 <= x < w:
                    out[r][x] = seq[j]
    return out
